-- SP_MPY_PR_MM_PCN_RecepcionFacturaEncabezado 1390,2446,27
CREATE PROCEDURE [dbo].[SP_MPY_PR_MM_PCN_RecepcionFacturaEncabezado] --2329, 23,2329
    -- Add the parameters for the stored procedure here
    @IdProveedor INT,
    @IdUsuario INT,
    @IdAceptacionPedido INT
AS
BEGIN

    -- SET NOCOUNT ON added to prevent extra result sets from
    -- interfering with SELECT statements.
    SET NOCOUNT ON;

	DECLARE @PROVEDORRFC NVARCHAR(20) = (SELECT RFC FROM dbo.S_Proveedor WHERE IdProveedor = @IdProveedor)

    SELECT ISNULL(F.ArchivoPDF,''),--0
           F.XML,--1
           AF.IdAceptacionPedido,--2
           AP.IdPedido,--3
           AF.CreadoEl,--4
           ISNULL(SV.VendorName,AP.IdSubContratista) AS Proveedor,--5
           E.Nombre,--6
           E.IdEstatus,--7
           F.IdFactura,--8
           (
				--SI VIENE  NULO SE SIMULA UN PDF EN BLANCO
               SELECT isnull(ComprobantePDFByte,)
               FROM dbo.FI_Factura
               WHERE IdFactura = F.IdFactura
           ) AS ComprobantePDFByte,--9
		   AF.IdAceptacionFactura,--10
		   ISNULL(AF.RegistroSAP,0), --11
		   ISNULL(AF.CuentaContable,''),--12
		   ISNULL(AF.CuentaCSH,''),--13
		   SES.SESNumber,
		   SES.SESReferenceNumber,
		   PSES.IdPRESES
    FROM MPY_MM_AceptacionFactura AS AF
        LEFT JOIN FI_Factura AS F
            ON F.IdFactura = AF.IdFactura
        LEFT JOIN TA_Estatus AS E
            ON E.IdEstatus = AF.IdEstatus
        LEFT JOIN MPY_MM_AceptacionPedido AS AP
            ON AP.IdAceptacionPedido = AF.IdAceptacionPedido
        LEFT JOIN S_Proveedor AS PR
            ON PR.RFC = AP.IdSubContratista
		LEFT JOIN Adinco.dbo.CO_SAPVendor AS SV
			ON SV.VendorIDSAP COLLATE SQL_Latin1_General_CP1_CI_AS = AP.IdSubContratista COLLATE SQL_Latin1_General_CP1_CI_AS
		LEFT JOIN Adinco.dbo.CO_SAPSES AS SES ON SES.PO_SAPNumer COLLATE Modern_Spanish_CI_AS = AP.IdPedido COLLATE Modern_Spanish_CI_AS AND SES.SESReferenceNumber COLLATE Modern_Spanish_CI_AS = AP.ReferenceNumber COLLATE Modern_Spanish_CI_AS
		LEFT JOIN Adinco.dbo.CO_SAPPRESES AS PSES ON PSES.SAPPONumber = SES.PO_SAPNumer AND PSES.SAPSESNumber = SES.SESReferenceNumber
    WHERE --AP.IdProveedor = @PROVEDORRFC AND 
	AF.IdAceptacionPedido = @IdAceptacionPedido
    GROUP BY F.ArchivoPDF,
             F.XML,
             AF.IdAceptacionPedido,
             AP.IdPedido,
             AF.CreadoEl,
             PR.RazonSocial,
             PR.RegimenCapital,
             E.Nombre,
             E.IdEstatus,
             PR.IdProveedor,
             F.IdFactura,
			 AF.IdAceptacionFactura,
			 AP.IdSubContratista,
			 SV.VendorIDSAP,
			 SV.VendorName,
			 AF.RegistroSAP,
			 AF.CuentaContable,
			 AF.CuentaCSH,
			 SES.SESNumber,
		     SES.SESReferenceNumber,
		     PSES.IdPRESES
--SELECT * FROM dbo.S_Usuario WHERE IdUsuario = 2313 


END;



